<script setup lang="ts">
// Author by Lab | zefry. All mutations use the owner's audited, versioned command boundary.
import { computed, nextTick, ref, watch } from 'vue';
import { locale } from '../i18n';
import WorkspaceIcon from './WorkspaceIcon.vue';
const props = defineProps<{ control: Record<string, any>; tab: string; detail: Record<string, any> | null; busy: boolean; reason: string }>();
const emit = defineEmits<{ command: [body: Record<string, unknown>]; close: []; reason: [value: string] }>();
const tr = (id: string, en: string) => locale.value === 'id' ? id : en;
const noc = computed(() => props.control.noc ?? {});
const totals = computed(() => noc.value.totals ?? {});
const sample = computed(() => noc.value.latest);
const configuration = ref(JSON.parse(JSON.stringify(props.control.configuration.configuration)));
const features: Record<string, [string, string]> = { pos: ['Kasir & penjualan', 'POS & selling'], catalog: ['Katalog', 'Catalog'], inventory: ['Persediaan', 'Inventory'], refunds: ['Pengembalian', 'Refunds'], reports: ['Laporan', 'Reports'], suppliers: ['Pemasok', 'Suppliers'], purchases: ['Pembelian', 'Purchasing'], customers: ['Pelanggan', 'Customers'], finance: ['Keuangan', 'Finance'], people: ['SDM', 'People'] };
const counts = computed(() => Object.entries(props.control.business_counts ?? {}) as [string, number][]);
const businessTotal = computed(() => counts.value.reduce((n, [, count]) => n + Number(count), 0));
const hourMax = computed(() => Math.max(1, ...(noc.value.hours ?? []).map((h: any) => h.requests)));
const errorRate = computed(() => totals.value.requests ? (100 * totals.value.server_errors / totals.value.requests).toFixed(2) : '0.00');
const now = Math.floor(Date.now() / 1000);
const healthy = computed(() => sample.value && sample.value.sampled_at >= now - configuration.value.worker_stale_seconds);
const date = (n: number) => n ? new Date(n * 1000).toLocaleString(locale.value === 'id' ? 'id-ID' : 'en-GB') : '—';
const number = (n: number) => Number(n ?? 0).toLocaleString(locale.value === 'id' ? 'id-ID' : 'en-GB');
const search = ref(''); const errorState = ref('all');
const errors = computed(() => (noc.value.errors ?? []).filter((e: any) => (errorState.value === 'all' || e.state === errorState.value) && `${e.code} ${e.route} ${e.correlation_id}`.toLowerCase().includes(search.value.toLowerCase())));
function command(action: string, body: Record<string, unknown>, version = 0) { emit('command', { action, version, reason: props.reason, ...body }); }
const draft = ref({ id: '', version: 0, name: '', subject: '', body: '', channel: 'in_app', locale: 'all' });
const preview = ref<Record<string, any> | null>(null); const review = ref(false); const schedule = ref(''); const previewBusy = ref(false); const previewError = ref('');
async function loadPreview(id: string) {
    previewBusy.value = true; previewError.value = ''; preview.value = null; review.value = false;
    try { const r = await fetch(`/platform/control/campaigns/${id}/preview`, { headers: { Accept: 'application/json' }, credentials: 'same-origin' }); if (!r.ok) throw new Error(); const data = await r.json(); preview.value = data.data ?? data; }
    catch { previewError.value = tr('Pratinjau belum tersedia. Muat ulang dan coba kembali.', 'Preview unavailable. Reload and try again.'); }
    finally { previewBusy.value = false; }
}
function queue() { if (!preview.value || !review.value) return; const due = schedule.value ? Math.floor(new Date(schedule.value).getTime() / 1000) : now; command('campaign.queue', { id: preview.value.id, review_digest: preview.value.digest, reviewed: true, due_at: due }, Number(preview.value.version)); }
const dialog = ref<HTMLDialogElement | null>(null); const business = ref<Record<string, any>>({}); const verified = ref(false); const resetIdentity = ref(''); const receipt = ref(''); const realCash = ref(false);
watch(() => props.detail, async d => {
    verified.value = false; resetIdentity.value = ''; receipt.value = ''; realCash.value = false;
    if (!d) { dialog.value?.close(); return; }
    business.value = { name: d.business.name, locale: d.business.locale, ...JSON.parse(JSON.stringify(d.controls)) };
    await nextTick(); dialog.value?.showModal();
}, { immediate: true });
function businessCommand(action: string, fields: Record<string, unknown> = {}) { if (props.detail) command(action, { id: props.detail.business.id, ...fields }, Number(props.detail.business.version)); }
</script>
<template>
<div class="control-operations">
  <template v-if="tab === 'overview'">
    <section class="kpis" aria-label="NOC metrics">
      <article><span><WorkspaceIcon name="activity"/>{{ tr('Permintaan · 24 jam','Requests · 24 hours') }}</span><strong>{{ number(totals.requests) }}</strong><small>{{ tr('Lalu lintas aplikasi terukur','Measured application traffic') }}</small></article>
      <article :class="{ warning: Number(errorRate) >= configuration.error_rate_warn_percent }"><span><WorkspaceIcon name="server"/>{{ tr('Kesalahan server','Server errors') }}</span><strong>{{ errorRate }}<em>%</em></strong><small>{{ number(totals.server_errors) }} HTTP 5xx</small></article>
      <article><span><WorkspaceIcon name="clock-3"/>{{ tr('Respons p95','p95 response') }}</span><strong>{{ !totals.requests ? '—' : noc.p95_over_3000 ? '> 3000' : '≤ ' + noc.p95_upper_bound_ms }}<em v-if="totals.requests">ms</em></strong><small>{{ tr('Batas histogram, bukan nilai eksak','Histogram bound, not an exact percentile') }}</small></article>
      <article><span><WorkspaceIcon name="users"/>{{ tr('Sesi aktif','Active sessions') }}</span><strong>{{ number(control.active_sessions) }}</strong><small>{{ tr('Seluruh bisnis yang dikelola','Across managed businesses') }}</small></article>
    </section>
    <div class="grid two-one">
      <section class="panel"><div class="panel-head"><div><p class="eyebrow">NETWORK OPERATIONS</p><h2>{{ tr('Aktivitas aplikasi','Application activity') }}</h2></div><span class="pill">24h</span></div><div v-if="noc.hours?.length" class="chart" role="img" :aria-label="tr('Permintaan HTTP dan kesalahan server per jam','Hourly HTTP requests and server errors')"><div v-for="hour in noc.hours" :key="hour.at" class="chart-column" :title="date(hour.at) + ': ' + hour.requests + ' requests, ' + hour.errors + ' errors'"><div class="bar-area"><div class="request-bar" :style="{ height: Math.max(2, 100 * hour.requests / hourMax) + '%' }"><i v-if="hour.errors" :style="{ height: Math.max(3, 100 * hour.errors / Math.max(1, hour.requests)) + '%' }"/></div></div><small>{{ new Date(hour.at * 1000).getHours().toString().padStart(2,'0') }}</small></div></div><p v-else class="empty">{{ tr('Grafik terisi setelah permintaan aplikasi tercatat.','The chart appears once application requests are recorded.') }}</p><p class="legend"><i/> HTTP <i class="error-dot"/> HTTP 5xx</p></section>
      <section class="panel"><div class="panel-head"><div><p class="eyebrow">BUSINESS NETWORK</p><h2>{{ tr('Status akun bisnis','Business account status') }}</h2></div><WorkspaceIcon name="building-2"/></div><strong class="total">{{ number(businessTotal) }}</strong><p class="muted">{{ tr('bisnis terdaftar','registered businesses') }}</p><div v-for="[state, count] in counts" :key="state" class="distribution"><div><span>{{ state }}</span><b>{{ count }}</b></div><progress :value="count" :max="businessTotal || 1"/></div><p v-if="!counts.length" class="empty">{{ tr('Belum ada bisnis terdaftar.','No registered businesses yet.') }}</p></section>
    </div>
    <section class="panel"><div class="panel-head"><div><p class="eyebrow">SERVICE HEALTH</p><h2>{{ tr('Kesehatan infrastruktur aplikasi','Application infrastructure health') }}</h2></div><span class="pill" :class="{warning: !healthy}">{{ healthy ? tr('Sampel terbaru','Recent sample') : tr('Perlu perhatian','Needs attention') }}</span></div><p class="muted">{{ tr('Diukur melalui cron. Sampel terakhir: ','Measured by cron. Latest sample: ') }}{{ date(sample?.sampled_at) }} · {{ tr('Cakupan proses aplikasi dan filesystem hosting.','Scope: application process and hosting filesystem.') }}</p><div class="table"><table><thead><tr><th>{{ tr('Layanan','Service') }}</th><th>Status</th><th>{{ tr('Pengukuran','Measurement') }}</th></tr></thead><tbody><tr><td><b>Database</b></td><td>{{ !healthy ? tr('Belum terverifikasi','Not verified') : sample.database.latency_ms >= configuration.database_warn_ms ? tr('Respons lambat','Slow response') : sample.database.state }}</td><td>{{ sample ? sample.database.latency_ms + ' ms · ' + sample.database.engine + ' · ' + sample.database.table_count + ' tables' : '—' }}</td></tr><tr><td><b>{{ tr('Worker email','Email worker') }}</b></td><td>{{ sample?.worker_at >= now - configuration.worker_stale_seconds ? tr('Berjalan','Running') : tr('Periksa cron','Check cron') }}</td><td>{{ date(sample?.worker_at) }}</td></tr><tr><td><b>{{ tr('Penyimpanan sesi','Session storage') }}</b></td><td>{{ !healthy ? '—' : sample.session_directory_writable ? tr('Dapat ditulis','Writable') : tr('Perlu perhatian','Needs attention') }}</td><td>{{ tr('Direktori sesi privat','Private session directory') }}</td></tr><tr><td><b>{{ tr('Kapasitas disk','Disk capacity') }}</b></td><td>{{ sample?.disk_free_bytes != null ? (sample.disk_free_bytes / 1073741824).toFixed(2) + ' GB ' + tr('tersedia','free') : '—' }}</td><td>{{ sample?.php_version ? 'PHP ' + sample.php_version : '—' }}</td></tr></tbody></table></div>
      <details class="history"><summary>{{ tr('Riwayat pengukuran database','Database measurement history') }}</summary><div class="table"><table><thead><tr><th>{{ tr('Waktu','Time') }}</th><th>Latency (ms)</th><th>Status</th></tr></thead><tbody><tr v-for="(s, i) in noc.samples" :key="i"><td>{{ date(s.sampled_at) }}</td><td>{{ s.database.latency_ms }}</td><td>{{ s.database.state }}</td></tr></tbody></table></div></details>
    </section>
  </template>
  <section v-if="tab === 'configuration'" class="panel">
    <p class="eyebrow">PLATFORM POLICY</p><h2>{{ tr('Konfigurasi seluruh bisnis','Configuration for all businesses') }}</h2><p class="muted">{{ tr('Izin pengguna tetap mengikuti peran. Menonaktifkan fitur menghentikan akses di server.','User access still follows assigned roles. Disabling a feature stops server access.') }}</p>
    <form @submit.prevent="command('settings.save', { configuration }, Number(control.configuration.version))"><fieldset :disabled="busy"><label class="toggle"><input v-model="configuration.registration_enabled" type="checkbox"/><span><b>{{ tr('Registrasi mandiri','Self registration') }}</b><small>{{ tr('Terima permohonan akun bisnis baru untuk ditinjau.','Accept new business applications for review.') }}</small></span></label><div class="feature-grid"><label v-for="(label, key) in features" :key="key" class="toggle"><input v-model="configuration.features[key]" type="checkbox"/><span>{{ tr(...label) }}</span></label></div><div class="fields"><label>{{ tr('Batas cron tanpa aktivitas (detik)','Worker stale threshold (seconds)') }}<input v-model.number="configuration.worker_stale_seconds" type="number" min="120" max="3600" step="1" required/></label><label>{{ tr('Peringatan database (ms)','Database warning (ms)') }}<input v-model.number="configuration.database_warn_ms" type="number" min="10" max="10000" step="1" required/></label><label>{{ tr('Peringatan error (%)','Error warning (%)') }}<input v-model.number="configuration.error_rate_warn_percent" type="number" min="1" max="50" step="1" required/></label></div><button class="primary" :disabled="!reason.trim()">{{ tr('Simpan konfigurasi','Save configuration') }}</button></fieldset></form>
  </section>
  <section v-if="tab === 'errors'" class="panel"><p class="eyebrow">INCIDENT TRACKING</p><h2>{{ tr('Pelacakan kode kesalahan','Error code tracking') }}</h2><p class="muted">{{ tr('Kode aman dan correlation ID untuk menelusuri masalah tanpa menampilkan data rahasia.','Safe codes and correlation IDs help investigate issues without exposing secrets.') }}</p><div class="fields"><label>{{ tr('Cari kode atau correlation ID','Search code or correlation ID') }}<input v-model="search" type="search"/></label><label>Status<select v-model="errorState"><option value="all">{{ tr('Semua','All') }}</option><option value="open">Open</option><option value="acknowledged">Acknowledged</option><option value="resolved">Resolved</option></select></label></div><div class="table"><table><thead><tr><th>{{ tr('Kode / rute','Code / route') }}</th><th>{{ tr('Kejadian','Occurrences') }}</th><th>Status</th><th>{{ tr('Tindakan','Actions') }}</th></tr></thead><tbody><tr v-for="e in errors" :key="e.id"><td><b>{{ e.code }}</b><small>{{ e.route }} · HTTP {{ e.http_status }}</small><code>{{ e.correlation_id }}</code><small>{{ date(e.last_seen) }}</small></td><td>{{ e.occurrences }}</td><td>{{ e.state }}</td><td><div class="actions"><button v-for="state in ['acknowledged','resolved','open'].filter(s => s !== e.state)" :key="state" :disabled="busy || !reason.trim()" @click="command('error.update', { id: e.id, state, resolution_note: reason }, Number(e.version))">{{ state === 'resolved' ? tr('Tandai selesai','Resolve') : state === 'open' ? tr('Buka kembali','Reopen') : tr('Sedang ditangani','Acknowledge') }}</button></div></td></tr><tr v-if="!errors.length"><td colspan="4" class="empty">{{ tr('Tidak ada insiden yang cocok.','No matching incidents.') }}</td></tr></tbody></table></div></section>
  <template v-if="tab === 'marketing'">
    <div class="grid two-one"><section class="panel"><p class="eyebrow">COMMUNICATIONS</p><h2>{{ tr('Buat informasi & kampanye','Create an announcement or campaign') }}</h2><p class="muted">{{ tr('Pengumuman aplikasi menjangkau bisnis aktif. Email hanya untuk penerima yang berlangganan.','In-app announcements reach active businesses. Email is limited to subscribed recipients.') }}</p><form @submit.prevent="command('campaign.save', { ...draft }, Number(draft.version))"><fieldset :disabled="busy"><label>{{ tr('Nama kampanye internal','Internal campaign name') }}<input v-model="draft.name" required maxlength="120"/></label><div class="fields"><label>{{ tr('Kanal','Channel') }}<select v-model="draft.channel"><option value="in_app">{{ tr('Pengumuman di aplikasi','In-app announcement') }}</option><option value="email">Email</option></select></label><label>{{ tr('Bahasa penerima','Recipient language') }}<select v-model="draft.locale"><option value="all">{{ tr('Semua bahasa','All languages') }}</option><option value="id">ID</option><option value="en">ENG</option></select></label></div><label>{{ tr('Judul','Subject') }}<input v-model="draft.subject" required maxlength="200"/></label><label>{{ tr('Isi pesan','Message') }}<textarea v-model="draft.body" rows="7" required maxlength="12000"/></label><button class="primary" :disabled="!reason.trim()">{{ tr('Simpan draf','Save draft') }}</button></fieldset></form></section>
    <section class="panel review"><p class="eyebrow">REVIEW BEFORE PUBLISH</p><h2>{{ tr('Pratinjau penerima & pesan','Audience & message preview') }}</h2><p v-if="!preview" class="muted">{{ previewBusy ? tr('Memuat…','Loading…') : tr('Simpan draf, lalu pilih Tinjau pada daftar kampanye.','Save a draft, then choose Review in the campaign list.') }}</p><p v-if="previewError" role="status">{{ previewError }}</p><template v-if="preview"><span class="pill">{{ preview.channel }} · {{ preview.count }} {{ tr('penerima','recipients') }}</span><h3>{{ preview.subject }}</h3><p class="message-preview">{{ preview.body }}</p><ul><li v-for="r in preview.recipients" :key="r.id">{{ r.email_hint }}</li></ul><form @submit.prevent="queue"><fieldset :disabled="busy"><label>{{ tr('Jadwalkan (opsional, zona waktu perangkat)','Schedule (optional, device time zone)') }}<input v-model="schedule" type="datetime-local"/></label><label class="toggle"><input v-model="review" type="checkbox"/><span>{{ tr('Saya telah memeriksa pesan dan penerimanya.','I reviewed the message and its recipients.') }}</span></label><button class="primary" :disabled="!reason.trim() || !review || !preview.count">{{ tr('Masukkan antrean publikasi','Queue publication') }}</button></fieldset></form></template></section></div>
    <section class="panel"><h2>{{ tr('Kampanye & laporan pengiriman','Campaigns & delivery reports') }}</h2><div class="table"><table><thead><tr><th>{{ tr('Kampanye','Campaign') }}</th><th>Status</th><th>{{ tr('Hasil','Outcomes') }}</th><th>{{ tr('Tindakan','Actions') }}</th></tr></thead><tbody><tr v-for="c in control.campaigns" :key="c.id"><td><b>{{ c.name }}</b><small>{{ c.channel }} · {{ c.locale }} · {{ date(c.due_at) }}</small></td><td>{{ c.status }}</td><td><span v-for="(n, outcome) in c.delivery" :key="outcome" class="outcome">{{ outcome }}: {{ n }}</span><span v-if="!Object.keys(c.delivery).length">—</span></td><td><div class="actions"><button v-if="c.status === 'draft'" :disabled="busy || previewBusy" @click="loadPreview(c.id)">{{ tr('Tinjau','Review') }}</button><button v-if="c.status !== 'cancelled'" :disabled="busy || !reason.trim()" @click="command('campaign.cancel', { id: c.id }, Number(c.version))">{{ tr('Batalkan','Cancel') }}</button></div></td></tr><tr v-if="!control.campaigns?.length"><td colspan="4" class="empty">{{ tr('Belum ada kampanye.','No campaigns yet.') }}</td></tr></tbody></table></div><p class="muted">{{ tr('Pembatalan menghentikan antrean berikutnya; pesan yang sudah dikirim atau sedang diproses tidak dapat ditarik kembali.','Cancellation stops pending work; already sent or in-flight messages cannot be recalled.') }}</p></section>
  </template>
  <dialog v-if="detail" ref="dialog" class="business-dialog" @cancel="busy ? $event.preventDefault() : emit('close')">
    <div class="dialog-head"><div><p class="eyebrow">BUSINESS ACCOUNT</p><h2>{{ detail.business.name }}</h2><p class="muted">{{ detail.business.email }} · {{ detail.business.status }}</p></div><button :disabled="busy" @click="emit('close')">{{ tr('Tutup','Close') }} ×</button></div>
    <label>{{ tr('Catatan tindakan','Action note') }}<input :value="reason" required maxlength="300" @input="emit('reason', ($event.target as HTMLInputElement).value)"/></label>
    <form @submit.prevent="businessCommand('business.configure', business)"><fieldset :disabled="busy"><div class="fields"><label>{{ tr('Nama bisnis','Business name') }}<input v-model="business.name" required maxlength="160"/></label><label>{{ tr('Bahasa','Language') }}<select v-model="business.locale"><option value="id">ID</option><option value="en">ENG</option></select></label><label>{{ tr('Label paket','Plan label') }}<input v-model="business.plan" required maxlength="32" pattern="[a-z0-9][a-z0-9_-]{0,31}"/></label></div><label>{{ tr('Catatan internal','Internal notes') }}<textarea v-model="business.notes" maxlength="1000" rows="2"/></label><div class="feature-grid"><label v-for="(label, key) in features" :key="key" class="toggle"><input v-model="business.features[key]" type="checkbox"/><span>{{ tr(...label) }}</span></label></div><button class="primary" :disabled="!reason.trim()">{{ tr('Simpan akun bisnis','Save business account') }}</button></fieldset></form>
    <section class="dialog-section"><h3>{{ tr('Identitas, peran & keamanan','Identities, roles & security') }}</h3><p class="muted">{{ tr('Reset TOTP mewajibkan pendaftaran authenticator baru dan mencabut sesi serta kode pemulihan lama. Kata sandi tetap berlaku.','TOTP reset requires new authenticator enrollment and revokes old sessions and recovery codes. The password remains valid.') }}</p><div class="table"><table><thead><tr><th>{{ tr('Identitas / peran','Identity / roles') }}</th><th>MFA</th><th>{{ tr('Sesi','Sessions') }}</th><th>{{ tr('Tindakan','Action') }}</th></tr></thead><tbody><tr v-for="identity in detail.identities" :key="identity.id"><td><code>{{ identity.id }}</code><small v-for="(role, i) in identity.roles" :key="i">{{ role.role }} · {{ role.scope }}</small></td><td>{{ identity.mfa }}</td><td>{{ identity.sessions }}</td><td><button :disabled="busy" @click="resetIdentity = identity.id; verified = false">{{ tr('Reset TOTP','Reset TOTP') }}</button></td></tr><tr v-if="!detail.identities.length"><td colspan="4">{{ tr('Identitas dibuat setelah aktivasi bisnis.','Identities are created upon business activation.') }}</td></tr></tbody></table></div><div v-if="resetIdentity" class="reset-confirm"><b>{{ tr('Konfirmasi identitas: ','Confirm identity: ') }}{{ resetIdentity }}</b><label class="toggle"><input v-model="verified" type="checkbox"/><span>{{ tr('Saya sudah memverifikasi identitas pemohon melalui saluran tepercaya.','I verified the requester’s identity through a trusted channel.') }}</span></label><button :disabled="busy || !verified || !reason.trim()" @click="businessCommand('security.totp_reset', { identity_id: resetIdentity, identity_verified: true })">{{ tr('Konfirmasi reset TOTP','Confirm TOTP reset') }}</button></div><button class="revoke" :disabled="busy || !reason.trim()" @click="businessCommand('security.sessions_revoke')">{{ tr('Cabut seluruh sesi bisnis','Revoke all business sessions') }}</button></section>
    <section class="dialog-section"><h3>{{ tr('Verifikasi pilot kas riil','Real-cash pilot verification') }}</h3><span class="pill">{{ detail.pilot.status }}</span><ul class="pilot-steps"><li v-for="(ready, step) in detail.pilot.steps" :key="step"><WorkspaceIcon :name="ready ? 'circle-check' : 'clock-3'" :size="16"/><b>{{ step }}</b><span>{{ ready ? tr('Bukti terkait tersedia','Linked evidence available') : tr('Belum ada bukti lengkap','Complete evidence pending') }}</span></li></ul><p class="muted">{{ tr('Katalog → pembukaan kasir → pembayaran tunai → penutupan shift. Status riil memerlukan bukti produksi dan konfirmasi pemilik.','Catalog → shift opening → cash payment → shift close. Real-cash status requires production evidence and owner attestation.') }}</p><form v-if="detail.pilot.status === 'READY_FOR_OWNER_ATTESTATION'" @submit.prevent="businessCommand('pilot.verify', { shift_id: detail.pilot.shift_id, evidence_digest: detail.pilot.evidence_digest, receipt_reference: receipt, real_cash_confirmed: realCash })"><label>{{ tr('Referensi struk / bukti kas','Receipt / cash evidence reference') }}<input v-model="receipt" maxlength="160" required/></label><label class="toggle"><input v-model="realCash" type="checkbox" required/><span>{{ tr('Saya memverifikasi transaksi menggunakan uang tunai riil di produksi.','I verified this transaction used real cash in production.') }}</span></label><button :disabled="busy || !reason.trim() || !realCash">{{ tr('Simpan konfirmasi pemilik','Record owner attestation') }}</button></form></section>
    <details class="history"><summary>{{ tr('Riwayat akun','Account history') }}</summary><p v-for="a in detail.audit" :key="a.id" class="muted">{{ date(a.occurred_at) }} · {{ a.action }} · {{ a.reason }}</p></details>
  </dialog>
</div>
</template>
